mapper.select:
SELECT DISTINCT /* LGVATT30070.retrieveSpecialOtRequestList */ REQ.REQUEST_NO AS REQUEST_NO ,TO_CHAR(NVL(SO.REQUEST_DATE, REQ.REQUEST_DATE), 'DD/MM/YYYY') AS REQUEST_DATE ,SO.SUBSIDIARY_CODE AS SUBSIDIARY_CODE ,USR.full_name_local || '/' ||NVL(USR.position_name, USR.title_name) ||'/'|| USR.organization_name_eng AS REQUESTOR ,SO.TIME_ATTEND_DETAIL_CODE AS TIME_ATTEND_DETAIL_CODE ,CD.COMMON_CODE_DESC AS ATTENDANCE_TYPE ,CD.TIME_AND_ATTENDANCE_NAME AS ATTENDANCE_TYPE_DETAIL ,SO.APPROVAL_REQUEST_ID AS APPROVAL_REQUEST_ID ,NVL(SO.PROGRESS_STATUS_CODE, REQ.PROCESS_STATUS_CODE) AS STATUS ,lgvhr_common_pkg.decode_lookup( 'LGVHR_ATT_APPROVAL_STATUS' ,lgvatt_common_pkg.get_approval_status( NVL(SO.approval_request_id, REQ.request_master_id) ,NVL(SO.request_code, REQ.request_code) ,USR.USER_NAME) ,NULL ,#{USER_SESSION.languageCode}) AS approval_status ,NVL(SO.REQUEST_CODE, REQ.REQUEST_CODE) AS REQUEST_CODE ,lgvatt_common_pkg.get_approval_status( NVL(SO.approval_request_id, REQ.request_master_id) , NVL(SO.request_code, REQ.request_code), '') AS STATUS_VAL FROM TB_ATT_SPECIAL_OT_RESULT_N SO LEFT OUTER JOIN LGCOM_APPROVAL_REQUEST_N REQ ON( SO.APPROVAL_REQUEST_ID = REQ.REQUEST_MASTER_ID AND SO.REQUEST_CODE = REQ.REQUEST_CODE) LEFT OUTER JOIN LGCOM_USER_M_V USR ON (SO.CREATION_USER_ID = USR.APPLICATION_USER_ID) LEFT OUTER JOIN (SELECT LCC.COMMON_CODE_DESC, CAC.TIME_AND_ATTENDANCE_CODE, CAC.TIME_AND_ATTENDANCE_NAME FROM LGCOM_COMMON_CODE_C LCC, TB_ATT_CODE_C CAC WHERE LCC.CODE_TYPE_CODE = 'LGVHR_ATTENDANCE_TYPE_CODE' AND LCC.COMMON_CODE = CAC.TIME_AND_ATTENDANCE_TYPE_CODE ) CD ON (SO.TIME_ATTEND_DETAIL_CODE = CD.TIME_AND_ATTENDANCE_CODE)
WHERE SO.REQUEST_DATE BETWEEN to_date(#{requestStartDate}, 'dd/mm/yyyy') AND to_date(#{requestEndDate}, 'dd/mm/yyyy')+1 AND SO.SUBSIDIARY_CODE = #{subsidiaryCode}
AND SO.CREATION_USER_ID = #{sessionUserId}
AND lgvatt_common_pkg.get_approval_status( NVL(SO.approval_request_id, REQ.request_master_id) , NVL(SO.request_code, REQ.request_code), '') = #{approvalStatusCode}
ORDER BY REQ.REQUEST_NO DESC
